UINT checks=0;DWORD settings[5]{};DWORD mainThread=0;constexpr char Body[]="MiniNT HTTP works\n";
void Check(bool value,const char* name){++checks;if(!value){std::printf("Internet client FAIL: %s error=%lu mode=%d\n",name,GetLastError(),INTERNET_CLIENT_MODE);ExitProcess(82);}}
void Load(int argc,char** argv){wchar_t path[1024]=L"C:\\App\\network.cfg";
#ifdef INTERNET_REFERENCE
 Check(argc==2,"reference configuration required");Check(MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,argv[1],-1,path,1024)>0,"configuration path");
#else
 (void)argc;(void)argv;
#endif
 char input[512]{};DWORD bytes=0;const auto file=CreateFileW(path,GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,0,nullptr);Check(file!=INVALID_HANDLE_VALUE&&ReadFile(file,input,sizeof(input)-1,&bytes,nullptr)&&CloseHandle(file),"owned test configuration");UINT at=0;for(auto& value:settings){while(input[at]==' '||input[at]=='\n'||input[at]=='\r')++at;Check(input[at]>='0'&&input[at]<='9',"configuration number");while(input[at]>='0'&&input[at]<='9'){value=value*10+DWORD(input[at++]-'0');Check(value<=65535,"configuration bound");}}}
void Root(){
#ifdef INTERNET_REFERENCE
 Check(false,"Native reference does not modify host trust stores");return;
#else
 if(settings[4]==2)return;BYTE certificate[512]{};DWORD bytes=0;const auto file=CreateFileW(L"C:\\App\\root.der",GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,0,nullptr);Check(file!=INVALID_HANDLE_VALUE&&ReadFile(file,certificate,sizeof(certificate),&bytes,nullptr)&&CloseHandle(file),"synthetic root input");const auto store=CertOpenSystemStoreW(0,L"ROOT");Check(store&&CertAddEncodedCertificateToStore(store,X509_ASN_ENCODING,certificate,bytes,CERT_STORE_ADD_USE_EXISTING,nullptr)&&CertCloseStore(store,0),"guest trust store populated");
#endif
}
SOCKET Connected(UINT port,int type=SOCK_STREAM){const auto socket=WSASocketW(AF_INET,type,type==SOCK_STREAM?IPPROTO_TCP:IPPROTO_UDP,nullptr,0,WSA_FLAG_OVERLAPPED);Check(socket!=INVALID_SOCKET,"Winsock socket");ADDRINFOA hints{};hints.ai_family=AF_INET;hints.ai_socktype=type;ADDRINFOA* address=nullptr;
#ifdef INTERNET_REFERENCE
 const char* name="127.0.0.1";hints.ai_flags=AI_NUMERICHOST;
#else
 const char* name="localhost";
#endif
 Check(getaddrinfo(name,nullptr,&hints,&address)==0&&address,"pinned address resolution");reinterpret_cast<sockaddr_in*>(address->ai_addr)->sin_port=htons(USHORT(port));const auto e=connect(socket,address->ai_addr,int(address->ai_addrlen));freeaddrinfo(address);Check(!e,"contained socket connection");return socket;}
void SendAll(SOCKET socket,const char* bytes,UINT count){UINT at=0;while(at<count){const auto sent=send(socket,bytes+at,int(count-at),0);Check(sent>0,"socket send");at+=UINT(sent);}}
void ReadExact(SOCKET socket,BYTE* bytes,UINT count){UINT at=0;while(at<count){const auto read=recv(socket,reinterpret_cast<char*>(bytes+at),int(count-at),0);Check(read>0,"socket receive");at+=UINT(read);}}
