int main(int argc,char** argv){mainThread=GetCurrentThreadId();Load(argc,argv);
#if INTERNET_CLIENT_MODE==0
 Sockets();
#elif INTERNET_CLIENT_MODE==1
 Http();
#elif INTERNET_CLIENT_MODE==2
 Async();
#elif INTERNET_CLIENT_MODE==3
 Timeout();
#elif INTERNET_CLIENT_MODE==4
 Tls();
#elif INTERNET_CLIENT_MODE==5
 Sspi();
#elif INTERNET_CLIENT_MODE==6
 Offline();
#else
 Simulated();
#endif
 std::printf("Internet client mode=%d PASS checks=%u\n",INTERNET_CLIENT_MODE,checks);return 0;}
